# Strategy:
# 1. Try baseline machine first.
cand_base = get_candidate(base_m)

best_cand = cand_base

# Check if we should look for alternatives
# Condition: Baseline is invalid OR Shift is large

look_for_alt = False
if cand_base is None:
    look_for_alt = True
elif cand_base['shift'] >= THRESH and current_mc < max_mc:
    look_for_alt = True
elif cand_base['start'] > anchor + THRESH and current_mc < max_mc:
    look_for_alt = True

if look_for_alt:
    # Find best alternative among other machines
    candidates_alt = []
    for m in allowed_machines_map:
        if m == base_m: 
            continue
        c = get_candidate(m)
        if c:
            # Check budget
            if c['mc'] == 1 and current_mc >= max_mc:
                continue
            candidates_alt.append(c)

    # Sort alternatives by (start, shift, machine) - we want earliest start/least shift
    # Since we already paid MC=1 (conceptually), we optimize for start/shift here.
    candidates_alt.sort(key=lambda x: (x['start'], x['shift'], x['machine']))

    cand_alt = candidates_alt[0] if candidates_alt else None

    if cand_alt:
        if cand_base is None:
            best_cand = cand_alt
        else:
            # Compare cand_base and cand_alt
            # Skill: if cand2.start < cand.start -> swap
            if cand_alt['start'] < cand_base['start']:
                 best_cand = cand_alt
            # Maybe also if start is same but shift is less? 
            # But usually start and shift are correlated if anchor is same.
            # Start = base_start + shift (if late) or base_start - shift (if early).
            # Here start >= anchor >= base_start (usually).
            # So smaller start means smaller shift.

# If still no candidate (should not happen if solvable), pick whatever available
if best_cand is None:
     for m in allowed_machines_map:
        c = get_candidate(m)
        if c:
            best_cand = c
            break
